package com.team2.wellness.engagement.ai.application;
import com.team2.wellness.engagement.port.out.ImageGenerationPort; import java.time.Duration; import java.util.Base64; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.reactive.function.client.*;
@Component public class OpenAiImageWebClient implements ImageGenerationPort {
 private final WebClient client; public OpenAiImageWebClient(@Value("${app.openai.base-url:https://api.openai.com}") String baseUrl,@Value("${app.openai.api-key:}") String key){client=WebClient.builder().baseUrl(baseUrl).defaultHeader(HttpHeaders.AUTHORIZATION,"Bearer "+key).build();}
 public ImageResult generate(ImageCommand command){ try { Response response=client.post().uri("/v1/images/generations").contentType(MediaType.APPLICATION_JSON).bodyValue(new Request("gpt-image-2",command.prompt(),"1024x1024","b64_json")).retrieve().onStatus(s->s.value()==429,x->x.createException().map(e->new ImageGenerationException("OPENAI_RATE_LIMIT"))).onStatus(HttpStatusCode::is5xxServerError,x->x.createException().map(e->new ImageGenerationException("OPENAI_SERVER_ERROR"))).onStatus(HttpStatusCode::isError,x->x.createException().map(e->new AiGenerationService.NonRetryable("OPENAI_MODERATION_OR_VALIDATION"))).bodyToMono(Response.class).block(Duration.ofSeconds(30)); if(response==null||response.data()==null||response.data().length==0) throw new ImageGenerationException("OPENAI_EMPTY_RESPONSE"); return new ImageResult(Base64.getDecoder().decode(response.data()[0].b64Json()),"image/png"); } catch(ImageGenerationException e){throw e;} catch(WebClientRequestException e){throw new ImageGenerationException("OPENAI_TIMEOUT");} }
 record Request(String model,String prompt,String size,String response_format){} record Response(Item[] data){} record Item(String b64_json){String b64Json(){return b64_json;}}
}
